    note: 'Transports: stdio (spawned) + remote (HTTP).',
    cliWiringSites: ['bin/fah.dart (mcpConfig)', 'lib/src/mcp/io_mcp_transport.dart', 'lib/src/mcp/mcp_http_transport.dart'],
