      }
        ..[HostCapability.jsApps] =
            CapabilityState.off('kiosk host renders no browser APIs')
        ..[HostCapability.mcp] =
            CapabilityState.transport({'remote'}, 'kiosk allows remote only');
      final profile = HostCapabilityProfile(name: 'kiosk', states: states);
