    note: 'roles.smol judge, overWindowRelief, contextWindowCap (#1077).',
    cliWiringSites: [
      'bin/fah.dart (compactionEngine, contextWindowCap)',
      'lib/src/cli/agent_cli.dart',
    ],
    surface: CapabilitySurface(
