      promptSectionIds: {'compaction'},
    ),
  ),
  HostCapability.loadModes: CapabilitySpec(
    capability: HostCapability.loadModes,
    title: 'Load modes + discover_tools',
    note: 'Essential-set demotion and the discover_tools registration.',
    cliWiringSites: [
