  HostCapability.sandboxEnv: (all: {}, defaults: {}),
  HostCapability.backgroundShellJobs: (
    all: {'process', 'future', 'async'},
    defaults: {'process'},
  ),
  HostCapability.sqliteLspDap: (
    all: {'ffi', 'process', 'sqljs'},
