            isA<CapabilityOffState>(),
            reason:
                '${entry.key}/${capability.id}: only the CLI wires this '
                'today',
          );
          expect(
            (state as CapabilityOffState).reason,
            contains('not wired'),
            reason: 'the off-reason must record the today-state',
          );
        }
      }
    });

